	uint8_t Role;  /* Connection role */
	uint8_t RemoteMasRxPHY;  /* Central Phy */
	uint8_t SequenceNumber;  /* Sequence number (b1 and b0 contain the lastest received SN and NESN) */
	uint16_t ConnEvent;  /* Connection Event Counter */
	uint32_t AnchorClk;  /* Anchor TIme in slot */
	uint16_t AnchorDelay;  /* Anchor Offset in microseconds */
